package com.ecole.gestion_scolaire.hr.service; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.entity.*; import com.ecole.gestion_scolaire.hr.enums.*; import com.ecole.gestion_scolaire.hr.repository.*; import com.ecole.gestion_scolaire.school.repository.*; import com.ecole.gestion_scolaire.identity.repository.*; import com.ecole.gestion_scolaire.common.exception.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; @Service @Transactional public class CompensationService { private final CompensationPlanRepository plans; private final TeacherRateRepository rates; private final EmployeeRepository employees; private final TeacherRepository teachers; private final SchoolYearRepository years; private final ClassGroupRepository classes; private final SubjectRepository subjects; private final UserAccountRepository users; public CompensationService(CompensationPlanRepository p,TeacherRateRepository r,EmployeeRepository e,TeacherRepository t,SchoolYearRepository y,ClassGroupRepository c,SubjectRepository s,UserAccountRepository u){plans=p;rates=r;employees=e;teachers=t;years=y;classes=c;subjects=s;users=u;} public CompensationPlanResponse createPlan(CompensationPlanRequest q){validate(q);var p=new CompensationPlan();p.setEmployee(employees.findById(q.employeeId()).orElseThrow(()->new ResourceNotFoundException("Employé introuvable")));p.setSchoolYear(q.schoolYearId()==null?null:years.findById(q.schoolYearId()).orElseThrow(()->new ResourceNotFoundException("Année scolaire introuvable")));p.setCompensationType(q.compensationType());p.setMonthlySalary(q.monthlySalary());p.setHourlyRate(q.hourlyRate());p.setFixedPart(q.fixedPart());p.setExpectedMonthlyHours(q.expectedMonthlyHours());p.setEffectiveFrom(q.effectiveFrom());p.setEffectiveUntil(q.effectiveUntil());String username=SecurityContextHolder.getContext().getAuthentication().getName();p.setCreatedBy(users.findByUsername(username).orElseThrow(()->new BusinessRuleException("Utilisateur courant introuvable")));return map(plans.save(p));} private void validate(CompensationPlanRequest q){if((q.compensationType()==CompensationType.MONTHLY||q.compensationType()==CompensationType.MIXED)&&(q.monthlySalary()==null||q.monthlySalary().signum()<0))throw new BusinessRuleException("Le salaire mensuel est obligatoire.");if((q.compensationType()==CompensationType.HOURLY||q.compensationType()==CompensationType.MIXED)&&q.hourlyRate()==null)throw new BusinessRuleException("Le tarif horaire de base est obligatoire.");} public TeacherRateResponse createRate(TeacherRateRequest q){var r=new TeacherRate();r.setTeacher(teachers.findById(q.teacherId()).orElseThrow(()->new ResourceNotFoundException("Enseignant introuvable")));r.setSchoolYear(years.findById(q.schoolYearId()).orElseThrow(()->new ResourceNotFoundException("Année scolaire introuvable")));r.setClassGroup(q.classGroupId()==null?null:classes.findById(q.classGroupId()).orElseThrow(()->new ResourceNotFoundException("Classe introuvable")));r.setSubject(q.subjectId()==null?null:subjects.findById(q.subjectId()).orElseThrow(()->new ResourceNotFoundException("Matière introuvable")));r.setWorkType(q.workType());r.setHourlyRate(q.hourlyRate());r.setEffectiveFrom(q.effectiveFrom());r.setEffectiveUntil(q.effectiveUntil());r.setActive(true);return map(rates.save(r));} @Transactional(readOnly=true) public List<CompensationPlanResponse> plans(Long employeeId){return plans.findByEmployeeIdOrderByEffectiveFromDesc(employeeId).stream().map(this::map).toList();} @Transactional(readOnly=true) public List<TeacherRateResponse> rates(Long teacherId){return rates.findByTeacherIdOrderByEffectiveFromDesc(teacherId).stream().map(this::map).toList();} private CompensationPlanResponse map(CompensationPlan p){return new CompensationPlanResponse(p.getId(),p.getEmployee().getId(),p.getSchoolYear()==null?null:p.getSchoolYear().getId(),p.getCompensationType(),p.getMonthlySalary(),p.getHourlyRate(),p.getFixedPart(),p.getExpectedMonthlyHours(),p.getEffectiveFrom(),p.getEffectiveUntil(),p.getStatus().name());} private TeacherRateResponse map(TeacherRate r){return new TeacherRateResponse(r.getId(),r.getTeacher().getId(),r.getSchoolYear().getId(),r.getClassGroup()==null?null:r.getClassGroup().getId(),r.getClassGroup()==null?null:r.getClassGroup().getName(),r.getSubject()==null?null:r.getSubject().getId(),r.getSubject()==null?null:r.getSubject().getName(),r.getWorkType(),r.getHourlyRate(),r.getEffectiveFrom(),r.getEffectiveUntil(),r.isActive());}}
